SELECT     c.id AS "Id do curso",     c.fullname AS "Curso",          COUNT(DISTINCT ue.id) AS "Total de usuários inscritos",          COUNT(DISTINCT CASE          WHEN cc.timecompleted IS NOT NULL THEN cc.userid      END) AS "Total de usuários concluídos",          ROUND(         (COUNT(DISTINCT CASE WHEN cc.timecompleted IS NOT NULL THEN cc.userid END)          / NULLIF(COUNT(DISTINCT ue.id), 0)) * 100,          2     ) AS "% Índice de conclusão"  FROM mdl_course c LEFT JOIN mdl_enrol e ON c.id = e.courseid LEFT JOIN mdl_user_enrolments ue ON e.id = ue.enrolid AND ue.status = 0 LEFT JOIN mdl_user u ON ue.userid = u.id AND u.deleted = 0 AND u.suspended = 0 LEFT JOIN mdl_course_completions cc ON cc.course = c.id AND cc.userid = ue.userid  WHERE     c.visible = 1     AND c.fullname NOT IN ('Senac', 'Curso Exclusivo - Modelo', 'Curso Livre - Modelo')  GROUP BY     c.id,     c.fullname  ORDER BY     "% Índice de conclusão" ASC,     c.id ASC  LIMIT 5;
